def choose_move(observation):
    def pos(v, d=None):
        if isinstance(v, dict):
            if "x" in v and "y" in v:
                return v["x"], v["y"]
            if "row" in v and "col" in v:
                return v["row"], v["col"]
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return d

    def add_positions(src, out):
        if isinstance(src, dict):
            for k in ("positions", "cells", "tiles", "points", "items", "locations", "targets"):
                if k in src:
                    add_positions(src.get(k), out)
            p = pos(src, None)
            if p is not None:
                out.append(p)
            return
        if isinstance(src, (list, tuple)):
            for a in src:
                q = pos(a, None)
                if q is not None:
                    out.append(q)

    w = observation.get("grid_width", 0) or observation.get("width", 0) or 0
    h = observation.get("grid_height", 0) or observation.get("height", 0) or 0

    sx, sy = pos(observation.get("self_position", observation.get("agent_position", (0, 0))), (0, 0))
    ox, oy = pos(observation.get("opponent_position", observation.get("enemy_position", (sx, sy))), (sx, sy))

    blocked = set()
    for key in ("obstacles", "walls", "blocked", "hazards"):
        for a in observation.get(key, []):
            q = pos(a, None)
            if q is not None:
                blocked.add(q)

    targets = []
    for key in ("resources", "resource_positions", "food", "pellets", "items", "goals", "objective_positions", "checkpoints"):
        add_positions(observation.get(key, []), targets)

    if not targets:
        for key in ("self_path", "path", "trail", "route", "visited"):
            add_positions(observation.get(key, []), targets)

    if not targets:
        for key in ("territory", "owned_cells", "my_territory", "unclaimed", "neutral_cells"):
            add_positions(observation.get(key, []), targets)

    if not targets and w and h:
        targets = [(w // 2, h // 2)]

    threat = abs(sx - ox) + abs(sy - oy)
    moves = [(0, 0), (1, 0), (-1, 0), (0, 1), (0, -1)]

    best_move = (0, 0)
    best_score = None

    for dx, dy in moves:
        nx, ny = sx + dx, sy + dy
        if nx < 0 or ny < 0 or (w and nx >= w) or (h and ny >= h) or (nx, ny) in blocked:
            continue

        score = 0

        if targets:
            td = 10**9
            for tx, ty in targets:
                d = abs(nx - tx) + abs(ny - ty)
                if d < td:
                    td = d
            score -= td * 8

        od = abs(nx - ox) + abs(ny - oy)
        if threat <= 3:
            score += od * 6
            if dx == 0 and dy == 0:
                score -= 4
        else:
            score += min(od, 4)

        if w and h:
            cx = (w - 1) / 2.0
            cy = (h - 1) / 2.0
            center_dist = abs(nx - cx) + abs(ny - cy)
            score -= center_dist * 0.5

        if dx == 0 and dy == 0:
            score -= 1

        if best_score is None or score > best_score or (score == best_score and (dx, dy) < best_move):
            best_score = score
            best_move = (dx, dy)

    return [best_move[0], best_move[1]]

